#### 2. **Use a Secrets Manager** ⚠️ HIGH PRIORITY
**Issue:** Loading secrets from `.env` files in production is insecure.

**Recommendation:** Implement a proper secrets manager. Here's an example using AWS Secrets Manager:

```javascript
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || "us-east-1" });
    this.cache = {};
  }

  async getSecret(secretName) {
    if (this.cache[secretName]) {
      return this.cache[secretName];
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);
      const secret = JSON.parse(response.SecretString);

      // Cache for 5 minutes
      this.cache[secretName] = secret;
      setTimeout(() => delete this.cache[secretName], 300000);

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error);
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

