const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // Log security event
      this.logSecurityEvent('SECRET_ACCESS_FAILED', {
        secretName,
        error: error.code
      });

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseConfig() {
    const dbSecret = await this.getSecret('app/database');
    return {
      host: dbSecret.host,
      port: dbSecret.port,
      database: dbSecret.database,
      username: dbSecret.username,
      password: dbSecret.password,
      ssl: { rejectUnauthorized: true }
    };
  }

  async getAWSCredentials() {
    return await this.getSecret('app/aws-credentials');
  }

  async getAPIKeys() {
    return await this.getSecret('app/api-keys');
  }

  async getStripeKey() {
    const keys = await this.getSecret('app/stripe');
    const environment = process.env.NODE_ENV || 'development';
    return environment === 'production' ? keys.live : keys.test;
  }

  clearCache() {
    this.cache.clear();
  }

  logSecurityEvent(event, details) {
    console.warn('SECURITY_EVENT:', {
      event,
      timestamp: new Date().toISOString(),
      ...details
    });
  }
}

// Singleton instance
let secretsManager;

const getSecretsManager = () => {
  if (!secretsManager) {
    secretsManager = new SecretsManager();
  }
  return secretsManager;
};

module.exports = { getSecretsManager };
