const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN // Only for initial auth
    });
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    try {
      // Use AppRole authentication for production
      if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
        const result = await this.client.approleLogin({
          role_id: process.env.VAULT_ROLE_ID,
          secret_id: process.env.VAULT_SECRET_ID
        });

        this.client.token = result.auth.client_token;

        // Set up token renewal
        this.setupTokenRenewal(result.auth.lease_duration);
      }

      this.initialized = true;
      console.log('✓ Vault authentication successful');
    } catch (error) {
      console.error('FATAL: Vault initialization failed:', error.message);
      throw error;
    }
  }

  async getSecret(path) {
    if (!this.initialized) {
      await this.initialize();
    }

    try {
      const result = await this.client.read(path);
      return result.data.data || result.data;
    } catch (error) {
      console.error(`Error reading secret from ${path}:`, error.message);
      throw new Error(`Failed to retrieve secret from ${path}`);
    }
  }

  async getDatabaseConfig() {
    // Vault can generate dynamic database credentials
    const creds = await this.client.read('database/creds/app-role');
    return {
      host: process.env.DB_HOST,
      port: process.env.DB_PORT,
      database: process.env.DB_NAME,
      username: creds.data.username,
      password: creds.data.password,
      // Credentials expire - lease_duration tells us when
      leaseDuration: creds.lease_duration
    };
  }

  setupTokenRenewal(leaseDuration) {
    // Renew token before it expires
    const renewInterval = (leaseDuration * 0.8) * 1000; // 80% of lease time

    setInterval(async () => {
      try {
        await this.client.tokenRenewSelf();
        console.log('✓ Vault token renewed');
      } catch (error) {
        console.error('Failed to renew Vault token:', error.message);
        // Re-authenticate
        this.initialized = false;
        await this.initialize();
      }
    }, renewInterval);
  }
}

module.exports = new VaultSecretsManager();
