    }

    this.validate();
    return this.config;
  }

  loadFromEnvFile() {
    const envPath = path.join(__dirname, '../.env');

    if (!fs.existsSync(envPath)) {
      throw new Error('.env file not found. Copy .env.example and configure it.');
    }

