/**
 * Secure Secrets Manager Implementation
 * Supports multiple backends: AWS Secrets Manager, HashiCorp Vault, Azure Key Vault
 * 
 * This replaces the insecure .env file approach with proper secrets management
 */

const AWS = require('aws-sdk');
const axios = require('axios');

// ==========================================
// CONFIGURATION
// ==========================================

const SECRETS_BACKEND = process.env.SECRETS_BACKEND || 'aws'; // 'aws', 'vault', 'azure', 'gcp'
const CACHE_TTL = 300000; // 5 minutes cache
const ENABLE_CACHING = process.env.SECRETS_CACHE !== 'false';

// ==========================================
// SECRET CACHE (In-Memory)
// ==========================================

class SecretCache {
  constructor(ttl = CACHE_TTL) {
    this.cache = new Map();
    this.ttl = ttl;
  }

  set(key, value) {
    this.cache.set(key, {
      value,
      timestamp: Date.now()
    });
  }

  get(key) {
    const cached = this.cache.get(key);
    if (!cached) return null;

    // Check if expired
    if (Date.now() - cached.timestamp > this.ttl) {
      this.cache.delete(key);
      return null;
    }

    return cached.value;
  }

  clear() {
    this.cache.clear();
  }

  delete(key) {
    this.cache.delete(key);
  }
}

const secretCache = new SecretCache();

// ==========================================
// AWS SECRETS MANAGER IMPLEMENTATION
// ==========================================

class AWSSecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    // Use IAM roles for authentication (no hardcoded keys!)
    // On ECS/EC2, credentials are automatically provided by IAM role
  }

  async getSecret(secretName) {
    try {
      // Check cache first
      if (ENABLE_CACHING) {
        const cached = secretCache.get(secretName);
        if (cached) {
          console.log(`[Secrets Manager] Cache hit for: ${secretName}`);
          return cached;
        }
      }

      console.log(`[Secrets Manager] Fetching from AWS: ${secretName}`);

      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the result
      if (ENABLE_CACHING) {
        secretCache.set(secretName, secret);
      }

      // Audit log
      this.auditLog('GET_SECRET', secretName, 'SUCCESS');

      return secret;
    } catch (error) {
      this.auditLog('GET_SECRET', secretName, 'FAILED', error.message);
      throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
    }
  }

  async createSecret(secretName, secretValue, description = '') {
    try {
      const params = {
        Name: secretName,
        SecretString: typeof secretValue === 'string' 
          ? secretValue 
          : JSON.stringify(secretValue),
        Description: description,
        KmsKeyId: process.env.KMS_KEY_ID // Use KMS for encryption
      };

      await this.client.createSecret(params).promise();
      this.auditLog('CREATE_SECRET', secretName, 'SUCCESS');

      return { success: true };
    } catch (error) {
      this.auditLog('CREATE_SECRET', secretName, 'FAILED', error.message);
      throw error;
    }
  }

  async rotateSecret(secretName, newValue) {
    try {
      await this.client.updateSecret({
        SecretId: secretName,
        SecretString: typeof newValue === 'string' 
          ? newValue 
          : JSON.stringify(newValue)
      }).promise();

      // Clear cache for this secret
      secretCache.delete(secretName);

      this.auditLog('ROTATE_SECRET', secretName, 'SUCCESS');
      return { success: true };
    } catch (error) {
      this.auditLog('ROTATE_SECRET', secretName, 'FAILED', error.message);
      throw error;
    }
  }

  auditLog(action, secretName, status, details = '') {
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      secretName,
      status,
      details,
      service: 'AWS_SECRETS_MANAGER',
      pid: process.pid
    };

    // In production, send to CloudWatch Logs, Splunk, or ELK
    console.log('[SECRETS AUDIT]', JSON.stringify(logEntry));
  }
}

// ==========================================
// HASHICORP VAULT IMPLEMENTATION
// ==========================================

class VaultSecretsManager {
  constructor() {
    this.vaultAddr = process.env.VAULT_ADDR || 'http://localhost:8200';
    this.vaultToken = process.env.VAULT_TOKEN; // Use AppRole in production
    this.vaultNamespace = process.env.VAULT_NAMESPACE || '';

    if (!this.vaultToken) {
      throw new Error('VAULT_TOKEN must be set');
    }
  }

  async getSecret(secretPath) {
    try {
      // Check cache first
      if (ENABLE_CACHING) {
        const cached = secretCache.get(secretPath);
        if (cached) {
          console.log(`[Vault] Cache hit for: ${secretPath}`);
          return cached;
        }
      }

      console.log(`[Vault] Fetching from Vault: ${secretPath}`);

      const headers = {
        'X-Vault-Token': this.vaultToken
      };

      if (this.vaultNamespace) {
        headers['X-Vault-Namespace'] = this.vaultNamespace;
      }

      const response = await axios.get(
        `${this.vaultAddr}/v1/${secretPath}`,
        { headers, timeout: 5000 }
      );

      const secret = response.data.data.data || response.data.data;

      // Cache the result
      if (ENABLE_CACHING) {
        secretCache.set(secretPath, secret);
      }

      this.auditLog('GET_SECRET', secretPath, 'SUCCESS');
      return secret;
    } catch (error) {
      this.auditLog('GET_SECRET', secretPath, 'FAILED', error.message);
      throw new Error(`Failed to retrieve secret ${secretPath}: ${error.message}`);
    }
  }

  async createSecret(secretPath, secretValue) {
    try {
      await axios.post(
        `${this.vaultAddr}/v1/${secretPath}`,
        { data: secretValue },
        {
          headers: {
            'X-Vault-Token': this.vaultToken,
            ...(this.vaultNamespace && { 'X-Vault-Namespace': this.vaultNamespace })
          }
        }
      );

      this.auditLog('CREATE_SECRET', secretPath, 'SUCCESS');
      return { success: true };
    } catch (error) {
      this.auditLog('CREATE_SECRET', secretPath, 'FAILED', error.message);
      throw error;
    }
  }

  async rotateSecret(secretPath, newValue) {
    try {
      await this.createSecret(secretPath, newValue);
      secretCache.delete(secretPath);
      this.auditLog('ROTATE_SECRET', secretPath, 'SUCCESS');
      return { success: true };
    } catch (error) {
      this.auditLog('ROTATE_SECRET', secretPath, 'FAILED', error.message);
      throw error;
    }
  }

  auditLog(action, secretPath, status, details = '') {
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      secretPath,
      status,
      details,
      service: 'HASHICORP_VAULT',
      pid: process.pid
    };

    console.log('[SECRETS AUDIT]', JSON.stringify(logEntry));
  }
}

