class AzureKeyVaultManager {
  constructor() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const vaultName = process.env.AZURE_KEYVAULT_NAME;
    if (!vaultName) {
      throw new Error('AZURE_KEYVAULT_NAME must be set');
    }

    const vaultUrl = `https://${vaultName}.vault.azure.net`;
    const credential = new DefaultAzureCredential();

    this.client = new SecretClient(vaultUrl, credential);
  }

  async getSecret(secretName) {
    try {
      // Check cache first
      if (ENABLE_CACHING) {
        const cached = secretCache.get(secretName);
        if (cached) {
          console.log(`[Azure Key Vault] Cache hit for: ${secretName}`);
          return cached;
        }
      }

      console.log(`[Azure Key Vault] Fetching: ${secretName}`);

      const secret = await this.client.getSecret(secretName);
      const value = JSON.parse(secret.value);

      if (ENABLE_CACHING) {
        secretCache.set(secretName, value);
      }

      this.auditLog('GET_SECRET', secretName, 'SUCCESS');
      return value;
    } catch (error) {
      this.auditLog('GET_SECRET', secretName, 'FAILED', error.message);
      throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
    }
  }

  async createSecret(secretName, secretValue) {
    try {
      const value = typeof secretValue === 'string' 
        ? secretValue 
        : JSON.stringify(secretValue);

      await this.client.setSecret(secretName, value);
      this.auditLog('CREATE_SECRET', secretName, 'SUCCESS');
      return { success: true };
    } catch (error) {
      this.auditLog('CREATE_SECRET', secretName, 'FAILED', error.message);
      throw error;
    }
  }

  async rotateSecret(secretName, newValue) {
    try {
      await this.createSecret(secretName, newValue);
      secretCache.delete(secretName);
      this.auditLog('ROTATE_SECRET', secretName, 'SUCCESS');
      return { success: true };
    } catch (error) {
      this.auditLog('ROTATE_SECRET', secretName, 'FAILED', error.message);
      throw error;
    }
  }

  auditLog(action, secretName, status, details = '') {
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      secretName,
      status,
      details,
      service: 'AZURE_KEY_VAULT',
      pid: process.pid
    };

    console.log('[SECRETS AUDIT]', JSON.stringify(logEntry));
  }
}

// ==========================================
// SECRETS MANAGER FACTORY
// ==========================================

class SecretsManager {
  constructor() {
    this.backend = this.initializeBackend();
  }

  initializeBackend() {
    console.log(`[Secrets Manager] Initializing backend: ${SECRETS_BACKEND}`);

    switch (SECRETS_BACKEND.toLowerCase()) {
      case 'aws':
        return new AWSSecretsManager();
      case 'vault':
        return new VaultSecretsManager();
      case 'azure':
        return new AzureKeyVaultManager();
      default:
        throw new Error(`Unsupported secrets backend: ${SECRETS_BACKEND}`);
    }
  }

  async getSecret(secretName) {
    return await this.backend.getSecret(secretName);
  }

  async createSecret(secretName, secretValue, description) {
    return await this.backend.createSecret(secretName, secretValue, description);
  }

  async rotateSecret(secretName, newValue) {
    return await this.backend.rotateSecret(secretName, newValue);
  }

  clearCache() {
    secretCache.clear();
    console.log('[Secrets Manager] Cache cleared');
  }
}

