// vault-secrets.js
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN, // Initial token, rotate regularly
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000;
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const result = await this.client.read(path);
      const secret = result.data.data || result.data;

      this.cache.set(path, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret from ${path}:`, error);
      throw new Error('Failed to retrieve secret from Vault');
    }
  }

  async renewToken() {
    try {
      await this.client.tokenRenewSelf();
    } catch (error) {
      console.error('Failed to renew Vault token:', error);
      throw error;
    }
  }
}

