const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000;
  }

  async getSecret(secretName, version = 'latest') {
    const cacheKey = `${secretName}:${version}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const name = `projects/${this.projectId}/secrets/${secretName}/versions/${version}`;
      const [version_data] = await this.client.accessSecretVersion({ name });

      const secret = version_data.payload.data.toString('utf8');

      this.cache.set(cacheKey, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secret from GCP Secret Manager');
    }
  }
}

module.exports = new GCPSecretsManager();
