// AWS Secrets Manager Integration
// Secure secrets loading for production

const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  /**
   * Get secret from AWS Secrets Manager with caching
   * @param {string} secretName - Name of the secret in AWS Secrets Manager
   * @param {boolean} forceRefresh - Force refresh from AWS
   * @returns {Promise<object>} Secret value parsed as JSON
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheTTL) {
      console.log(`Using cached secret: ${secretName}`);
      return cached.value;
    }

    try {
      console.log(`Fetching secret from AWS Secrets Manager: ${secretName}`);

      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      });

      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      // Log access for audit trail
      this.logSecretAccess(secretName);

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // Return cached value if available, even if expired
      if (cached) {
        console.warn(`Using expired cached secret: ${secretName}`);
        return cached.value;
      }

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get multiple secrets in parallel
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>} Object with secret names as keys
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => 
      this.getSecret(name).then(value => ({ name, value }))
    );

    const results = await Promise.all(promises);

    return results.reduce((acc, { name, value }) => {
      acc[name] = value;
      return acc;
    }, {});
  }

  /**
   * Clear cache for a specific secret or all secrets
   * @param {string} secretName - Optional secret name to clear
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`Cleared cache for secret: ${secretName}`);
    } else {
      this.cache.clear();
      console.log('Cleared all secrets cache');
    }
  }

  /**
   * Log secret access for audit trail
   * @param {string} secretName - Name of the secret accessed
   */
  logSecretAccess(secretName) {
    // In production, send to CloudWatch Logs or your logging service
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      event: 'secret_access',
      secretName,
      service: process.env.SERVICE_NAME || 'app',
      environment: process.env.NODE_ENV || 'development'
    }));
  }

  /**
   * Graceful rotation handler - call this when secrets are rotated
   * @param {string} secretName - Name of rotated secret
   */
  async handleRotation(secretName) {
    console.log(`Handling rotation for secret: ${secretName}`);
    this.clearCache(secretName);
    return await this.getSecret(secretName, true);
  }
}

// Singleton instance
let secretsManagerInstance = null;

/**
 * Get or create SecretsManager instance
 * @returns {SecretsManager}
 */
function getSecretsManager() {
  if (!secretsManagerInstance) {
    secretsManagerInstance = new SecretsManager();
  }
  return secretsManagerInstance;
}

/**
 * Initialize application secrets from AWS Secrets Manager
 * Call this at application startup
 */
async function initializeSecrets() {
  const NODE_ENV = process.env.NODE_ENV || 'development';

  // In development, use .env file
  if (NODE_ENV === 'development') {
    console.log('Development mode: Using .env file for secrets');
    require('dotenv').config();
    return;
  }

  // In production, use AWS Secrets Manager
  console.log('Production mode: Loading secrets from AWS Secrets Manager');

  const secretsManager = getSecretsManager();
  const secretName = process.env.AWS_SECRET_NAME || `${process.env.SERVICE_NAME}/production`;

  try {
    const secrets = await secretsManager.getSecret(secretName);

    // Inject secrets into process.env
    // This allows existing code using process.env to work without changes
    Object.keys(secrets).forEach(key => {
      if (!process.env[key]) {
        process.env[key] = secrets[key];
      }
    });

    console.log('Successfully loaded secrets from AWS Secrets Manager');

    // Validate required secrets are present
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
      'STRIPE_SECRET_KEY'
    ];

    const missingSecrets = requiredSecrets.filter(key => !process.env[key]);
    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

  } catch (error) {
    console.error('Failed to initialize secrets:', error);
    process.exit(1);
  }
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  initializeSecrets
};

