### 2. **JWT-Based Authentication** (Better than API keys)
```javascript
const jwt = require('jsonwebtoken');

const authenticateJWT = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    logger.warn(`Invalid token from ${req.ip}`);
    return res.status(403).json({ error: 'Invalid token' });
  }
};
```

### 3. **Database Security** (When you add a database)
```javascript
// Use parameterized queries (PostgreSQL example)
const { Pool } = require('pg');
const pool = new Pool({
  ssl: { rejectUnauthorized: true },
  max: 10,
  connectionTimeoutMillis: 3000,
});

// GOOD - Parameterized query
app.get('/user/:id', async (req, res) => {
  const result = await pool.query(
    'SELECT * FROM users WHERE id = $1',
    [req.params.id]
  );
  res.json(result.rows);
});

// BAD - SQL Injection vulnerable
// app.get('/user/:id', async (req, res) => {
//   const result = await pool.query(
//     `SELECT * FROM users WHERE id = ${req.params.id}`
//   );
// });
```

### 4. **Content Security Policy**
```javascript
// More restrictive CSP
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'"],
    imgSrc: ["'self'", 'data:'],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));
```

### 5. **Session Security** (If using sessions)
```javascript
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const { createClient } = require('redis');

const redisClient = createClient();
redisClient.connect();

app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  name: 'sessionId',
  cookie: {
    secure: true, // HTTPS only
    httpOnly: true, // No JS access
    maxAge: 1800000, // 30 minutes
    sameSite: 'strict',
  },
}));
```

