// config/secrets.js
// Production-ready secrets management using AWS Secrets Manager

const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

const NodeCache = require('node-cache');
const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console(),
  ],
});

// Cache secrets for 5 minutes to reduce API calls
const secretsCache = new NodeCache({ 
  stdTTL: 300,
  checkperiod: 60,
  useClones: false, // Don't clone secrets in memory
});

// Initialize AWS Secrets Manager client
const client = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
  // Use IAM roles in production, never hardcode credentials
  maxAttempts: 3,
  requestTimeout: 5000,
});

/**
 * Retrieve a secret from AWS Secrets Manager
 * @param {string} secretName - Name of the secret in AWS Secrets Manager
 * @param {boolean} forceRefresh - Force refresh from AWS (skip cache)
 * @returns {Promise<Object>} Parsed secret value
 */
async function getSecret(secretName, forceRefresh = false) {
  try {
    // Check cache first (unless force refresh)
    if (!forceRefresh) {
      const cachedSecret = secretsCache.get(secretName);
      if (cachedSecret) {
        logger.debug(`Secret ${secretName} retrieved from cache`);
        return cachedSecret;
      }
    }

    // Retrieve from AWS Secrets Manager
    logger.info(`Fetching secret ${secretName} from AWS Secrets Manager`);

    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT', // Always get current version
    });

    const response = await client.send(command);

    let secretValue;
    if (response.SecretString) {
      secretValue = JSON.parse(response.SecretString);
    } else {
      // Handle binary secrets
      const buff = Buffer.from(response.SecretBinary, 'base64');
      secretValue = buff.toString('ascii');
    }

    // Cache the secret
    secretsCache.set(secretName, secretValue);

    logger.info(`Secret ${secretName} retrieved successfully`);
    return secretValue;

  } catch (error) {
    logger.error(`Failed to retrieve secret ${secretName}:`, {
      error: error.message,
      code: error.code,
    });

    // Handle specific errors
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret ${secretName} not found in Secrets Manager`);
    } else if (error.name === 'InvalidRequestException') {
      throw new Error(`Invalid request for secret ${secretName}`);
    } else if (error.name === 'InvalidParameterException') {
      throw new Error(`Invalid parameter for secret ${secretName}`);
    }

    throw error;
  }
}

/**
 * Load all application secrets
 * @returns {Promise<Object>} Object containing all secrets
 */
async function loadSecrets() {
  const environment = process.env.NODE_ENV || 'development';
  const appName = process.env.APP_NAME || 'express-app';

  try {
    logger.info(`Loading secrets for ${appName} in ${environment} environment`);

    // Load secrets in parallel for better performance
    const [
      databaseSecrets,
      awsSecrets,
      apiSecrets,
      paymentSecrets,
      monitoringSecrets,
    ] = await Promise.all([
      getSecret(`${appName}/${environment}/database`),
      getSecret(`${appName}/${environment}/aws`),
      getSecret(`${appName}/${environment}/api-keys`),
      getSecret(`${appName}/${environment}/payment`),
      getSecret(`${appName}/${environment}/monitoring`),
    ]);

    return {
      database: databaseSecrets,
      aws: awsSecrets,
      apiKeys: apiSecrets,
      payment: paymentSecrets,
      monitoring: monitoringSecrets,
    };

  } catch (error) {
    logger.error('Failed to load secrets:', error);

    // In development, allow fallback to .env (with warning)
    if (environment === 'development') {
      logger.warn('⚠️  DEVELOPMENT MODE: Falling back to .env file');
      logger.warn('⚠️  NEVER use .env files in production!');
      return loadSecretsFromEnv();
    }

    // In production, fail fast - don't start without secrets
    throw new Error('Failed to load secrets. Application cannot start.');
  }
}

/**
 * Fallback for development - load from environment variables
 * WARNING: Only use in development!
 */
function loadSecretsFromEnv() {
  logger.warn('Loading secrets from environment variables (DEVELOPMENT ONLY)');

  return {
    database: {
      url: process.env.DATABASE_URL,
      maxConnections: parseInt(process.env.DB_MAX_CONNECTIONS || '10', 10),
    },
    aws: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: process.env.AWS_REGION,
    },
    apiKeys: {
      anthropic: process.env.ANTHROPIC_API_KEY,
      internal: process.env.INTERNAL_API_KEYS?.split(',') || [],
    },
    payment: {
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      stripeWebhookSecret: process.env.STRIPE_WEBHOOK_SECRET,
    },
    monitoring: {
      logfireToken: process.env.LOGFIRE_TOKEN,
    },
  };
}

/**
 * Rotate secrets - call this periodically
 */
async function rotateSecrets() {
  logger.info('Rotating secrets cache');
  secretsCache.flushAll();
  return loadSecrets();
}

/**
 * Clear secrets from memory on shutdown
 */
function clearSecrets() {
  logger.info('Clearing secrets from memory');
  secretsCache.flushAll();
  secretsCache.close();
}

/**
 * Validate that all required secrets are present
 */
function validateSecrets(secrets) {
  const required = [
    'database.url',
    'apiKeys.internal',
  ];

  const missing = required.filter(path => {
    const parts = path.split('.');
    let obj = secrets;
    for (const part of parts) {
      if (!obj || !obj[part]) return true;
      obj = obj[part];
    }
    return false;
  });

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  logger.info('All required secrets validated');
}

module.exports = {
  getSecret,
  loadSecrets,
  rotateSecrets,
  clearSecrets,
  validateSecrets,
};

// config/vault-secrets.js
// Production-ready secrets management using HashiCorp Vault

const vault = require('node-vault');
const NodeCache = require('node-cache');
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console(),
  ],
});

// Cache secrets for 5 minutes
const secretsCache = new NodeCache({ 
  stdTTL: 300,
  checkperiod: 60,
  useClones: false,
});

let vaultClient = null;
let tokenRenewalTimer = null;

/**
 * Initialize Vault client
 */
async function initializeVault() {
  const options = {
    apiVersion: 'v1',
    endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
    requestOptions: {
      timeout: 5000,
    },
  };

  vaultClient = vault(options);

  // Authenticate with Vault
  try {
    const authMethod = process.env.VAULT_AUTH_METHOD || 'kubernetes';

    switch (authMethod) {
      case 'token':
        // Use token authentication (not recommended for production)
        if (!process.env.VAULT_TOKEN) {
          throw new Error('VAULT_TOKEN not set');
        }
        vaultClient.token = process.env.VAULT_TOKEN;
        logger.info('Authenticated with Vault using token');
        break;

      case 'kubernetes':
        // Kubernetes service account authentication
        await authenticateWithKubernetes();
        break;

      case 'aws':
        // AWS IAM authentication
        await authenticateWithAWS();
        break;

      default:
        throw new Error(`Unsupported auth method: ${authMethod}`);
    }

    // Set up token renewal
    await setupTokenRenewal();

    logger.info('Vault client initialized successfully');
  } catch (error) {
    logger.error('Failed to initialize Vault:', error);
    throw error;
  }
}

/**
 * Authenticate with Kubernetes
 */
async function authenticateWithKubernetes() {
  const fs = require('fs').promises;
  const jwt = await fs.readFile(
    '/var/run/secrets/kubernetes.io/serviceaccount/token',
    'utf8'
  );

  const result = await vaultClient.kubernetesLogin({
    role: process.env.VAULT_ROLE || 'app',
    jwt: jwt,
  });

  vaultClient.token = result.auth.client_token;
  logger.info('Authenticated with Vault using Kubernetes');
}

/**
 * Authenticate with AWS IAM
 */
async function authenticateWithAWS() {
  const result = await vaultClient.awsIamLogin({
    role: process.env.VAULT_ROLE || 'app-role',
  });

  vaultClient.token = result.auth.client_token;
  logger.info('Authenticated with Vault using AWS IAM');
}

/**
 * Set up automatic token renewal
 */
async function setupTokenRenewal() {
  try {
    const tokenInfo = await vaultClient.tokenLookupSelf();
    const ttl = tokenInfo.data.ttl;

    // Renew token at 80% of its TTL
    const renewalTime = (ttl * 0.8) * 1000;

    tokenRenewalTimer = setInterval(async () => {
      try {
        await vaultClient.tokenRenewSelf();
        logger.info('Vault token renewed successfully');
      } catch (error) {
        logger.error('Failed to renew Vault token:', error);
        // Try to re-authenticate
        await initializeVault();
      }
    }, renewalTime);

    logger.info(`Token renewal scheduled every ${renewalTime / 1000} seconds`);
  } catch (error) {
    logger.error('Failed to set up token renewal:', error);
  }
}

/**
 * Get secret from Vault
 */
async function getSecret(path, forceRefresh = false) {
  if (!vaultClient) {
    throw new Error('Vault client not initialized. Call initializeVault() first.');
  }

  try {
    // Check cache first
    if (!forceRefresh) {
      const cachedSecret = secretsCache.get(path);
      if (cachedSecret) {
        logger.debug(`Secret ${path} retrieved from cache`);
        return cachedSecret;
      }
    }

    logger.info(`Fetching secret from Vault: ${path}`);

    // Read from Vault KV v2 (default in newer versions)
    const result = await vaultClient.read(path);
    const secretValue = result.data.data || result.data;

    // Cache the secret
    secretsCache.set(path, secretValue);

    logger.info(`Secret ${path} retrieved successfully`);
    return secretValue;

  } catch (error) {
    logger.error(`Failed to retrieve secret ${path}:`, error);
    throw error;
  }
}

/**
 * Load all application secrets from Vault
 */
async function loadSecrets() {
  const environment = process.env.NODE_ENV || 'development';
  const appName = process.env.APP_NAME || 'express-app';
  const basePath = `secret/data/${appName}/${environment}`;

  try {
    logger.info(`Loading secrets from Vault path: ${basePath}`);

    const [
      databaseSecrets,
      awsSecrets,
      apiSecrets,
      paymentSecrets,
      monitoringSecrets,
    ] = await Promise.all([
      getSecret(`${basePath}/database`),
      getSecret(`${basePath}/aws`),
      getSecret(`${basePath}/api-keys`),
      getSecret(`${basePath}/payment`),
      getSecret(`${basePath}/monitoring`),
    ]);

    return {
      database: databaseSecrets,
      aws: awsSecrets,
      apiKeys: apiSecrets,
      payment: paymentSecrets,
      monitoring: monitoringSecrets,
    };

  } catch (error) {
    logger.error('Failed to load secrets from Vault:', error);
    throw error;
  }
}

/**
 * Clean up on shutdown
 */
function cleanup() {
  if (tokenRenewalTimer) {
    clearInterval(tokenRenewalTimer);
  }
  secretsCache.flushAll();
  secretsCache.close();
  logger.info('Vault secrets manager cleaned up');
}

module.exports = {
  initializeVault,
  getSecret,
  loadSecrets,
  cleanup,
};

