**Create a secrets manager module (`secrets.js`):**

```javascript
const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  /**
   * Retrieve a secret from AWS Secrets Manager with caching
   * @param {string} secretName - The name/ARN of the secret
   * @returns {Promise<Object>} The parsed secret value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Handle binary secrets
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Load all application secrets
   * @returns {Promise<Object>} All application secrets
   */
  async loadSecrets() {
    const environment = process.env.NODE_ENV || 'development';
    const secretName = `${process.env.APP_NAME || 'myapp'}/${environment}`;

    try {
      const secrets = await this.getSecret(secretName);

      // Validate required secrets
      const required = [
        'DATABASE_URL',
        'JWT_SECRET',
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY'
      ];

      const missing = required.filter(key => !secrets[key]);
      if (missing.length > 0) {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      }

      return secrets;
    } catch (error) {
      if (environment === 'development') {
        console.warn('Falling back to .env file for development');
        require('dotenv').config();
        return process.env;
      }
      throw error;
    }
  }

  /**
   * Clear the secrets cache
   */
  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

