const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN,
    });
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(path);
      return result.data.data; // Vault KV v2 format
    } catch (error) {
      console.error(`Error reading secret from Vault: ${path}`, error);
      throw error;
    }
  }

  async loadSecrets() {
    const environment = process.env.NODE_ENV || 'development';
    const path = `secret/data/${process.env.APP_NAME}/${environment}`;

    return await this.getSecret(path);
  }
}

module.exports = new VaultSecretsManager();
