/**
 * AWS Secrets Manager Integration
 * Securely load secrets from AWS Secrets Manager
 */

const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour in milliseconds
  }

  /**
   * Retrieve a secret from AWS Secrets Manager with caching
   * @param {string} secretName - Name of the secret in AWS Secrets Manager
   * @param {boolean} forceRefresh - Force cache refresh
   * @returns {Promise<Object>} - Parsed secret value
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      });

      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // If it's a network error and we have a cached value, use it
      if (this.cache.has(secretName) && error.name === 'NetworkingError') {
        console.warn(`Using stale cached value for ${secretName} due to network error`);
        return this.cache.get(secretName).value;
      }

      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  /**
   * Clear cached secrets (useful for testing or rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Rotate secret and clear cache
   * @param {string} secretName - Name of the secret to rotate
   */
  async rotateSecret(secretName) {
    this.cache.delete(secretName);
    return await this.getSecret(secretName, true);
  }
}

// Singleton instance
let instance = null;

const getSecretsManager = () => {
  if (!instance) {
    instance = new SecretsManager();
  }
  return instance;
};

module.exports = { SecretsManager, getSecretsManager };

/**
 * HashiCorp Vault Integration
 * Securely load secrets from Vault
 */

const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Initialize Vault client with AppRole authentication
   * More secure than using root tokens
   */
  async initWithAppRole(roleId, secretId) {
    try {
      const result = await this.client.approleLogin({
        role_id: roleId,
        secret_id: secretId
      });

      this.client.token = result.auth.client_token;

      // Set up token renewal
      this.setupTokenRenewal(result.auth.lease_duration);

      return true;
    } catch (error) {
      console.error('Failed to authenticate with Vault:', error.message);
      throw error;
    }
  }

  /**
   * Set up automatic token renewal
   */
  setupTokenRenewal(leaseDuration) {
    // Renew at 80% of lease duration
    const renewInterval = (leaseDuration * 0.8) * 1000;

    setInterval(async () => {
      try {
        await this.client.tokenRenewSelf();
        console.log('Vault token renewed successfully');
      } catch (error) {
        console.error('Failed to renew Vault token:', error.message);
        // Implement alerting here
      }
    }, renewInterval);
  }

  /**
   * Read secret from Vault KV v2
   * @param {string} path - Secret path (e.g., 'app/production/database')
   * @param {boolean} forceRefresh - Force cache refresh
   */
  async getSecret(path, forceRefresh = false) {
    // Check cache
    if (!forceRefresh && this.cache.has(path)) {
      const cached = this.cache.get(path);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      // For KV v2, need to add 'data' to path
      const result = await this.client.read(`secret/data/${path}`);
      const secretValue = result.data.data;

      // Cache the secret
      this.cache.set(path, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret from path ${path}:`, error.message);

      // Return cached value on error if available
      if (this.cache.has(path)) {
        console.warn(`Using stale cached value for ${path}`);
        return this.cache.get(path).value;
      }

      throw error;
    }
  }

  /**
   * Read dynamic database credentials
   * These are auto-generated and have TTL
   */
  async getDatabaseCredentials(dbName) {
    try {
      const result = await this.client.read(`database/creds/${dbName}`);
      return {
        username: result.data.username,
        password: result.data.password,
        leaseId: result.lease_id,
        leaseDuration: result.lease_duration
      };
    } catch (error) {
      console.error(`Error retrieving database credentials for ${dbName}:`, error.message);
      throw error;
    }
  }

  /**
   * Revoke a lease (for dynamic credentials)
   */
  async revokeLease(leaseId) {
    try {
      await this.client.request({
        path: '/sys/leases/revoke',
        method: 'PUT',
        json: { lease_id: leaseId }
      });
      console.log(`Lease ${leaseId} revoked successfully`);
    } catch (error) {
      console.error(`Error revoking lease ${leaseId}:`, error.message);
      throw error;
    }
  }

  /**
   * Clear cached secrets
   */
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
let instance = null;

const getVaultSecretsManager = () => {
  if (!instance) {
    instance = new VaultSecretsManager();
  }
  return instance;
};

module.exports = { VaultSecretsManager, getVaultSecretsManager };

/**
 * Azure Key Vault Integration
 * Securely load secrets from Azure Key Vault
 */

const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureKeyVaultManager {
  constructor() {
    const vaultName = process.env.AZURE_KEYVAULT_NAME;

    if (!vaultName) {
      throw new Error('AZURE_KEYVAULT_NAME environment variable is required');
    }

    const vaultUrl = `https://${vaultName}.vault.azure.net`;

    // Use DefaultAzureCredential which supports:
    // - Managed Identity (recommended for production)
    // - Azure CLI (for local development)
    // - Environment variables
    const credential = new DefaultAzureCredential();

    this.client = new SecretClient(vaultUrl, credential);
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Retrieve a secret from Azure Key Vault
   * @param {string} secretName - Name of the secret
   * @param {string} version - Optional version of the secret
   * @param {boolean} forceRefresh - Force cache refresh
   */
  async getSecret(secretName, version = '', forceRefresh = false) {
    const cacheKey = `${secretName}:${version}`;

    // Check cache
    if (!forceRefresh && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const secret = await this.client.getSecret(secretName, { version });

      // Cache the secret
      this.cache.set(cacheKey, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // Return cached value on error if available
      if (this.cache.has(cacheKey)) {
        console.warn(`Using stale cached value for ${secretName}`);
        return this.cache.get(cacheKey).value;
      }

      throw error;
    }
  }

  /**
   * Get all versions of a secret (useful for rotation)
   */
  async getSecretVersions(secretName) {
    try {
      const versions = [];
      for await (const properties of this.client.listPropertiesOfSecretVersions(secretName)) {
        versions.push({
          version: properties.version,
          enabled: properties.enabled,
          createdOn: properties.createdOn,
          updatedOn: properties.updatedOn
        });
      }
      return versions;
    } catch (error) {
      console.error(`Error listing versions for ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Parse a connection string secret and return as object
   */
  async getSecretAsObject(secretName) {
    const secretValue = await this.getSecret(secretName);

    try {
      return JSON.parse(secretValue);
    } catch (error) {
      // If not JSON, return as string
      return { value: secretValue };
    }
  }

  /**
   * Clear cached secrets
   */
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
let instance = null;

const getAzureKeyVaultManager = () => {
  if (!instance) {
    instance = new AzureKeyVaultManager();
  }
  return instance;
};

module.exports = { AzureKeyVaultManager, getAzureKeyVaultManager };

/**
 * Google Cloud Secret Manager Integration
 * Securely load secrets from GCP Secret Manager
 */

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    // Client automatically uses GOOGLE_APPLICATION_CREDENTIALS or default credentials
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour

    if (!this.projectId) {
      throw new Error('GCP_PROJECT_ID environment variable is required');
    }
  }

  /**
   * Access a secret version
   * @param {string} secretName - Name of the secret
   * @param {string} version - Version (default: 'latest')
   * @param {boolean} forceRefresh - Force cache refresh
   */
  async getSecret(secretName, version = 'latest', forceRefresh = false) {
    const cacheKey = `${secretName}:${version}`;

    // Check cache
    if (!forceRefresh && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const name = `projects/${this.projectId}/secrets/${secretName}/versions/${version}`;
      const [response] = await this.client.accessSecretVersion({ name });

      const secretValue = response.payload.data.toString('utf8');

      // Cache the secret
      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // Return cached value on error if available
      if (this.cache.has(cacheKey)) {
        console.warn(`Using stale cached value for ${secretName}`);
        return this.cache.get(cacheKey).value;
      }

      throw error;
    }
  }

  /**
   * Get secret as JSON object
   */
  async getSecretAsJSON(secretName, version = 'latest') {
    const secretValue = await this.getSecret(secretName, version);
    try {
      return JSON.parse(secretValue);
    } catch (error) {
      throw new Error(`Secret ${secretName} is not valid JSON`);
    }
  }

  /**
   * List all versions of a secret
   */
  async listSecretVersions(secretName) {
    try {
      const parent = `projects/${this.projectId}/secrets/${secretName}`;
      const [versions] = await this.client.listSecretVersions({ parent });

      return versions.map(version => ({
        name: version.name,
        state: version.state,
        createTime: version.createTime,
        destroyTime: version.destroyTime
      }));
    } catch (error) {
      console.error(`Error listing versions for ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Create a new secret
   */
  async createSecret(secretName, secretValue) {
    try {
      const parent = `projects/${this.projectId}`;

      // Create the secret
      const [secret] = await this.client.createSecret({
        parent,
        secretId: secretName,
        secret: {
          replication: {
            automatic: {}
          }
        }
      });

      // Add the secret version
      const [version] = await this.client.addSecretVersion({
        parent: secret.name,
        payload: {
          data: Buffer.from(secretValue, 'utf8')
        }
      });

      return version;
    } catch (error) {
      console.error(`Error creating secret ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Clear cached secrets
   */
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
let instance = null;

const getGCPSecretsManager = () => {
  if (!instance) {
    instance = new GCPSecretsManager();
  }
  return instance;
};

module.exports = { GCPSecretsManager, getGCPSecretsManager };

/**
 * Unified Secrets Configuration Loader
 * Supports multiple secret backends with graceful fallback
 */

class ConfigLoader {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';
    this.secretsProvider = process.env.SECRETS_PROVIDER || 'env'; // env, aws, vault, azure, gcp
    this.config = {};
  }

  /**
   * Initialize the appropriate secrets manager
   */
  async initialize() {
    console.log(`Initializing secrets provider: ${this.secretsProvider}`);

    switch (this.secretsProvider.toLowerCase()) {
      case 'aws':
        const { getSecretsManager } = require('./secrets-manager-aws');
        this.secretsManager = getSecretsManager();
        break;

      case 'vault':
        const { getVaultSecretsManager } = require('./secrets-manager-vault');
        this.secretsManager = getVaultSecretsManager();

        // Initialize with AppRole if credentials provided
        if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
          await this.secretsManager.initWithAppRole(
            process.env.VAULT_ROLE_ID,
            process.env.VAULT_SECRET_ID
          );
        }
        break;

      case 'azure':
        const { getAzureKeyVaultManager } = require('./secrets-manager-azure');
        this.secretsManager = getAzureKeyVaultManager();
        break;

      case 'gcp':
        const { getGCPSecretsManager } = require('./secrets-manager-gcp');
        this.secretsManager = getGCPSecretsManager();
        break;

      case 'env':
      default:
        // Fallback to environment variables (NOT RECOMMENDED for production)
        if (this.environment === 'production') {
          console.warn('⚠️  WARNING: Using environment variables for secrets in production is not recommended!');
        }
        this.secretsManager = null;
        break;
    }
  }

  /**
   * Load all required secrets
   */
  async loadSecrets() {
    try {
      if (this.secretsManager) {
        // Load from secrets manager
        await this.loadFromSecretsManager();
      } else {
        // Load from environment variables
        this.loadFromEnvironment();
      }

      // Validate all required secrets are present
      this.validateSecrets();

      return this.config;
    } catch (error) {
      console.error('Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Load secrets from the configured secrets manager
   */
  async loadFromSecretsManager() {
    const secretsMapping = {
      aws: {
        database: `app/${this.environment}/database`,
        api_keys: `app/${this.environment}/api-keys`,
        jwt: `app/${this.environment}/jwt`
      },
      vault: {
        database: `app/${this.environment}/database`,
        api_keys: `app/${this.environment}/api-keys`,
        jwt: `app/${this.environment}/jwt`
      },
      azure: {
        database: `app-${this.environment}-database`,
        api_keys: `app-${this.environment}-api-keys`,
        jwt: `app-${this.environment}-jwt`
      },
      gcp: {
        database: `app-${this.environment}-database`,
        api_keys: `app-${this.environment}-api-keys`,
        jwt: `app-${this.environment}-jwt`
      }
    };

    const paths = secretsMapping[this.secretsProvider];

    try {
      // Load database credentials
      const dbSecrets = await this.secretsManager.getSecret(paths.database);
      this.config.database = typeof dbSecrets === 'string' 
        ? JSON.parse(dbSecrets) 
        : dbSecrets;

      // Load API keys
      const apiSecrets = await this.secretsManager.getSecret(paths.api_keys);
      this.config.apiKeys = typeof apiSecrets === 'string' 
        ? JSON.parse(apiSecrets) 
        : apiSecrets;

      // Load JWT secret
      const jwtSecrets = await this.secretsManager.getSecret(paths.jwt);
      this.config.jwt = typeof jwtSecrets === 'string' 
        ? JSON.parse(jwtSecrets) 
        : jwtSecrets;

    } catch (error) {
      console.error('Error loading secrets from secrets manager:', error);
      throw error;
    }
  }

  /**
   * Load from environment variables (fallback - not recommended for production)
   */
  loadFromEnvironment() {
    // Only allow in development or if explicitly enabled
    if (this.environment === 'production' && !process.env.ALLOW_ENV_SECRETS) {
      throw new Error('Environment variable secrets not allowed in production. Use a secrets manager.');
    }

    this.config = {
      database: {
        url: process.env.DATABASE_URL,
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        username: process.env.DB_USERNAME,
        password: process.env.DB_PASSWORD,
        database: process.env.DB_NAME
      },
      apiKeys: {
        aws: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        },
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY
      },
      jwt: {
        secret: process.env.JWT_SECRET,
        expiry: process.env.JWT_EXPIRY || '1h'
      }
    };
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets() {
    const requiredPaths = [
      'jwt.secret'
    ];

    const missing = [];

    for (const path of requiredPaths) {
      const value = this.getNestedValue(this.config, path);
      if (!value) {
        missing.push(path);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  /**
   * Get nested value from object using dot notation
   */
  getNestedValue(obj, path) {
    return path.split('.').reduce((current, key) => current?.[key], obj);
  }

  /**
   * Get a specific secret value
   */
  get(path, defaultValue = null) {
    return this.getNestedValue(this.config, path) || defaultValue;
  }

  /**
   * Mask sensitive values for logging
   */
  maskSecret(value) {
    if (!value) return null;

    const str = String(value);
    if (str.length <= 8) return '***';

    return `${str.substring(0, 4)}...${str.substring(str.length - 4)}`;
  }

  /**
   * Get configuration summary (safe for logging)
   */
  getSummary() {
    return {
      environment: this.environment,
      secretsProvider: this.secretsProvider,
      database: {
        configured: !!this.config.database?.url || !!this.config.database?.host,
        url: this.config.database?.url ? this.maskSecret(this.config.database.url) : undefined
      },
      jwt: {
        configured: !!this.config.jwt?.secret,
        secret: this.config.jwt?.secret ? this.maskSecret(this.config.jwt.secret) : undefined
      },
      apiKeys: {
        aws: !!this.config.apiKeys?.aws?.accessKeyId,
        anthropic: !!this.config.apiKeys?.anthropic,
        stripe: !!this.config.apiKeys?.stripe
      }
    };
  }
}

// Singleton instance
let instance = null;

const getConfigLoader = () => {
  if (!instance) {
    instance = new ConfigLoader();
  }
  return instance;
};

module.exports = { ConfigLoader, getConfigLoader };

/**
 * Secure Express Application with Secrets Manager Integration
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { getConfigLoader } = require('./config-loader');

const app = express();

// Flag to track if app is initialized
let initialized = false;
let config = null;

/**
 * Initialize application with secrets from secrets manager
 */
async function initializeApp() {
  if (initialized) {
    return config;
  }

  try {
    console.log('🔐 Initializing application with secure secrets management...');

    // Load configuration and secrets
    const configLoader = getConfigLoader();
    await configLoader.initialize();
    config = await configLoader.loadSecrets();

    // Log configuration summary (safe - no actual secrets)
    console.log('✅ Configuration loaded:', configLoader.getSummary());

    initialized = true;
    return config;
  } catch (error) {
    console.error('❌ Failed to initialize application:', error.message);
    throw error;
  }
}

// ===== SECURITY MIDDLEWARE =====

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration (will be enhanced after config loads)
