// SECURE VERSION - Production-ready Express Application
// Implements OWASP Top 10 security controls

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const hpp = require('hpp');
const compression = require('compression');
const { body, param, validationResult } = require('express-validator');

const app = express();

// ========================================
// 1. SECURITY HEADERS (helmet)
// ========================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  frameguard: {
    action: 'deny',
  },
  noSniff: true,
  xssFilter: true,
}));

// ========================================
// 2. CORS CONFIGURATION
// ========================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// ========================================
// 3. RATE LIMITING
// ========================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests, please try again later.',
});

app.use('/api/', generalLimiter);

// ========================================
// 4. BODY PARSING & SIZE LIMITS
// ========================================
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========================================
// 5. DATA SANITIZATION
// ========================================
// Sanitize against NoSQL injection
app.use(mongoSanitize());

// Sanitize against XSS
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// ========================================
// 6. COMPRESSION
// ========================================
app.use(compression());

// ========================================
// 7. REQUEST LOGGING (Security Events)
// ========================================
const securityLogger = (req, res, next) => {
  const logData = {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip || req.connection.remoteAddress,
    userAgent: req.get('user-agent'),
    // In production, send to proper logging service (e.g., Winston, Bunyan)
  };

  // Log suspicious patterns
  if (req.path.includes('..') || 
      req.path.includes('<script>') ||
      req.path.includes('SELECT') ||
      req.path.includes('UNION')) {
    console.warn('⚠️  SECURITY ALERT - Suspicious request:', logData);
  }

  next();
};

app.use(securityLogger);

// ========================================
// 8. AUTHENTICATION MIDDLEWARE
// ========================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'No token provided' 
    });
  }

  // In production, verify JWT token
  // jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
  //   if (err) return res.status(403).json({ error: 'Invalid token' });
  //   req.user = user;
  //   next();
  // });

  // Placeholder for demo
  if (token !== 'valid-token-example') {
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Invalid token' 
    });
  }

  req.user = { id: 1, role: 'user' };
  next();
};

// ========================================
// 9. AUTHORIZATION MIDDLEWARE
// ========================================
const authorizeRoles = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'You do not have permission to access this resource' 
      });
    }
    next();
  };
};

// ========================================
// 10. INPUT VALIDATION HELPERS
// ========================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ========================================
// ROUTES (Secured)
// ========================================

// Public health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint with authentication
app.get('/users', 
  authenticateToken,
  (req, res) => {
    // In production, query database with parameterized queries
    // const users = await db.query('SELECT id, name, email FROM users');

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
      count: users.length
    });
  }
);

// Get specific user with validation
app.get('/users/:id',
  authenticateToken,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  validateRequest,
  (req, res) => {
    const userId = req.params.id;

    // In production, use parameterized queries
    // const user = await db.query('SELECT * FROM users WHERE id = ?', [userId]);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found',
        message: 'User not found' 
      });
    }

    res.json({
      success: true,
      data: user
    });
  }
);

// Create user with validation
app.post('/users',
  authenticateToken,
  authorizeRoles('admin'),
  strictLimiter,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address')
      .isLength({ max: 100 })
      .withMessage('Email too long'),
  ],
  validateRequest,
  (req, res) => {
    const { name, email } = req.body;

    // In production, use parameterized queries
    // const result = await db.query(
    //   'INSERT INTO users (name, email) VALUES (?, ?)',
    //   [name, email]
    // );

    const newUser = {
      id: 3,
      name,
      email,
      createdAt: new Date().toISOString()
    };

    console.log('✅ User created:', { id: newUser.id, name: newUser.name });

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  }
);

// ========================================
// ERROR HANDLING
// ========================================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource does not exist',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('❌ Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: 'Error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ========================================
// SERVER CONFIGURATION
// ========================================
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Secure server running on port ${PORT}`);
  console.log(`📝 Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('⚠️  SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('✅ Process terminated');
    process.exit(0);
  });
});

process.on('unhandledRejection', (err) => {
  console.error('❌ Unhandled rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

