  const { url } = req.body;

  // Validate URL
  if (!validator.isURL(url, { protocols: ['http', 'https'] })) {
    return res.status(400).json({ error: 'Invalid URL' });
  }

  // Whitelist allowed domains
  const allowedDomains = ['api.example.com', 'trusted-api.com'];
  const urlObj = new URL(url);

  if (!allowedDomains.includes(urlObj.hostname)) {
    return res.status(403).json({ error: 'Domain not allowed' });
  }

  // Prevent internal network access
  if (urlObj.hostname.startsWith('192.168.') || 
      urlObj.hostname.startsWith('10.') ||
      urlObj.hostname === 'localhost' ||
      urlObj.hostname === '127.0.0.1') {
    return res.status(403).json({ error: 'Internal network access denied' });
  }

  // Safe to make request
  fetch(url).then(response => response.json()).then(data => res.json(data));
});
