/**
 * SECURE SECRETS MANAGEMENT - AWS Secrets Manager Integration
 * 
 * This module provides secure secret retrieval from AWS Secrets Manager
 * with caching, error handling, and rotation support.
 */

const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Retrieve a secret from AWS Secrets Manager
   * @param {string} secretName - Name/ARN of the secret
   * @param {boolean} useCache - Whether to use cached value
   * @returns {Promise<Object>} Parsed secret value
   */
  async getSecret(secretName, useCache = true) {
    try {
      // Check cache first
      if (useCache && this.cache.has(secretName)) {
        const cached = this.cache.get(secretName);
        if (Date.now() - cached.timestamp < this.cacheTimeout) {
          console.log(`📦 Using cached secret: ${secretName}`);
          return cached.value;
        }
        // Cache expired, remove it
        this.cache.delete(secretName);
      }

      console.log(`🔐 Fetching secret from AWS Secrets Manager: ${secretName}`);

      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.client.send(command);

      // Parse secret (supports both string and binary secrets)
      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      console.log(`✅ Secret retrieved successfully: ${secretName}`);
      return secretValue;

    } catch (error) {
      console.error(`❌ Error fetching secret ${secretName}:`, error.message);

      // Specific error handling
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      } else if (error.name === 'AccessDeniedException') {
        throw new Error(`Access denied to secret: ${secretName}`);
      } else if (error.name === 'InvalidRequestException') {
        throw new Error(`Invalid request for secret: ${secretName}`);
      }

      throw error;
    }
  }

  /**
   * Refresh a secret in the cache
   * Call this when you detect a secret rotation
   */
  async refreshSecret(secretName) {
    this.cache.delete(secretName);
    return await this.getSecret(secretName, false);
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache.clear();
    console.log('🧹 Secret cache cleared');
  }

  /**
   * Retrieve multiple secrets in parallel
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => this.getSecret(name));
    return await Promise.all(promises);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

/**
 * Initialize application secrets from AWS Secrets Manager
 * Call this at application startup
 */
async function initializeSecrets() {
  try {
    console.log('🔐 Initializing secrets from AWS Secrets Manager...');

    const secretName = process.env.AWS_SECRET_NAME || 'prod/myapp/secrets';
    const secrets = await secretsManager.getSecret(secretName);

    // Validate required secrets
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
      'REDIS_PASSWORD',
    ];

    const missingSecrets = requiredSecrets.filter(key => !secrets[key]);
    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Inject secrets into process.env (for compatibility with existing code)
    // In production, avoid this and use getSecret() directly
    Object.keys(secrets).forEach(key => {
      if (!process.env[key]) {
        process.env[key] = secrets[key];
      }
    });

    console.log('✅ Secrets initialized successfully');
    return secrets;

  } catch (error) {
    console.error('❌ Failed to initialize secrets:', error.message);

    // In production, fail fast if secrets can't be loaded
    if (process.env.NODE_ENV === 'production') {
      console.error('🔴 Cannot start application without secrets. Exiting...');
      process.exit(1);
    }

    throw error;
  }
}

/**
 * Middleware to check if secrets are initialized
 */
function ensureSecretsInitialized(req, res, next) {
  if (!process.env.JWT_SECRET) {
    return res.status(503).json({
      error: 'Service Unavailable',
      message: 'Application secrets not initialized'
    });
  }
  next();
}

/**
 * Health check that includes secrets status
 */
async function secretsHealthCheck() {
  try {
    const secretName = process.env.AWS_SECRET_NAME || 'prod/myapp/secrets';
    await secretsManager.getSecret(secretName);
    return {
      status: 'healthy',
      message: 'Secrets Manager accessible'
    };
  } catch (error) {
    return {
      status: 'unhealthy',
      message: error.message
    };
  }
}

module.exports = {
  secretsManager,
  initializeSecrets,
  ensureSecretsInitialized,
  secretsHealthCheck,
};

