/**
 * Secrets Manager Integration
 * Loads secrets from AWS Secrets Manager instead of .env files
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = null;
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes cache
    this.environment = process.env.NODE_ENV || 'development';
  }

  /**
   * Initialize the secrets manager client
   */
  initialize() {
    // Only use AWS Secrets Manager in production
    if (this.environment === 'production' || process.env.USE_SECRETS_MANAGER === 'true') {
      this.client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
        // Use IAM roles in production (no hardcoded credentials)
        // Credentials will be automatically loaded from EC2/ECS instance role
      });
      console.log('✅ AWS Secrets Manager initialized');
    } else {
      console.log('⚠️  Development mode: Using local configuration (not Secrets Manager)');
    }
  }

  /**
   * Retrieve a secret from AWS Secrets Manager
   * @param {string} secretName - Name of the secret in AWS Secrets Manager
   * @param {boolean} useCache - Whether to use cached value
   * @returns {Promise<Object>} - Parsed secret value
   */
  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    // In development, fall back to local config
    if (!this.client) {
      return this.getLocalSecret(secretName);
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT', // Always get the latest version
      });

      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Handle binary secrets if needed
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = JSON.parse(buff.toString('ascii'));
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      console.log(`✅ Retrieved secret: ${secretName}`);
      return secretValue;

    } catch (error) {
      console.error(`❌ Error retrieving secret ${secretName}:`, error.message);

      // Log but don't expose secret details
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret '${secretName}' not found in Secrets Manager`);
      } else if (error.name === 'AccessDeniedException') {
        throw new Error(`Access denied to secret '${secretName}'. Check IAM permissions.`);
      } else {
        throw new Error(`Failed to retrieve secret '${secretName}'`);
      }
    }
  }

  /**
   * Get secret from local configuration (development only)
   * @param {string} secretName - Name of the secret
   * @returns {Object} - Local configuration
   */
  getLocalSecret(secretName) {
    // Use environment variables in development
    // These should NOT contain real secrets - only dev/test values
    const localSecrets = {
      'app/database': {
        host: process.env.DB_HOST || 'localhost',
        port: process.env.DB_PORT || 5432,
        database: process.env.DB_NAME || 'dev_db',
        username: process.env.DB_USER || 'dev_user',
        password: process.env.DB_PASSWORD || 'dev_password',
      },
      'app/api-keys': {
        jwtSecret: process.env.JWT_SECRET || 'dev-jwt-secret-change-in-production',
        anthropicApiKey: process.env.ANTHROPIC_API_KEY || '',
        stripeSecretKey: process.env.STRIPE_SECRET_KEY || 'sk-test-dev_key',
      },
      'app/aws': {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID || '',
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || '',
        region: process.env.AWS_REGION || 'us-east-1',
      },
      'app/monitoring': {
        logfireToken: process.env.LOGFIRE_TOKEN || '',
      },
    };

    if (!localSecrets[secretName]) {
      throw new Error(`Local secret '${secretName}' not configured`);
    }

    console.log(`⚠️  Using local configuration for: ${secretName}`);
    return localSecrets[secretName];
  }

  /**
   * Load all application secrets
   * @returns {Promise<Object>} - All secrets needed by the application
   */
  async loadAllSecrets() {
    try {
      const [database, apiKeys, aws, monitoring] = await Promise.all([
        this.getSecret('app/database'),
        this.getSecret('app/api-keys'),
        this.getSecret('app/aws'),
        this.getSecret('app/monitoring'),
      ]);

      return {
        database,
        apiKeys,
        aws,
        monitoring,
      };
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Clear the secrets cache (useful for rotation)
   */
  clearCache() {
    this.cache.clear();
    console.log('🔄 Secrets cache cleared');
  }

  /**
   * Validate that all required secrets are present
   * @param {Object} secrets - Secrets object to validate
   * @throws {Error} - If required secrets are missing
   */
  validateSecrets(secrets) {
    const required = {
      database: ['host', 'port', 'database', 'username', 'password'],
      apiKeys: ['jwtSecret'],
    };

    const missing = [];

    for (const [category, fields] of Object.entries(required)) {
      if (!secrets[category]) {
        missing.push(`${category} (entire category)`);
        continue;
      }

      for (const field of fields) {
        if (!secrets[category][field]) {
          missing.push(`${category}.${field}`);
        }
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log('✅ All required secrets validated');
  }
}

