  // Secrets health check - shows if secrets are properly loaded (no sensitive data)
  app.get('/health/secrets', (req, res) => {
    const secretsStatus = {
      database: !!secrets.database?.host,
      jwtSecret: !!secrets.apiKeys?.jwtSecret,
      aws: !!secrets.aws?.accessKeyId,
      monitoring: !!secrets.monitoring?.logfireToken,
    };

    res.json({
      status: 'ok',
      secretsConfigured: secretsStatus,
      timestamp: new Date().toISOString()
    });
  });

  // Users endpoint - protected with authentication
  app.get('/users', authenticateToken, (req, res) => {
    try {
      // In real application, this would query the database using secrets.database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sanitize output based on user permissions
      const sanitizedUsers = users.map(user => ({
        id: user.id,
        name: user.name,
        ...(req.user.role === 'admin' && { email: user.email })
      }));

      res.json(sanitizedUsers);
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // User by ID with validation
  app.get('/users/:id',
    authenticateToken,
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    (req, res) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id, 10);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      const sanitizedUser = {
        id: user.id,
        name: user.name,
        ...(req.user.role === 'admin' && { email: user.email })
      };

      res.json(sanitizedUser);
    }
  );

  // ============================================
  // ERROR HANDLING
  // ============================================

  // 404 handler
  app.use((req, res, next) => {
    res.status(404).json({ error: 'Resource not found' });
  });

  // Global error handler
  app.use((err, req, res, next) => {
    console.error('Error:', err);

    const isDevelopment = process.env.NODE_ENV === 'development';

    res.status(err.status || 500).json({
      error: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    });
  });

  return app;
}

/**
 * Start the server
 */
async function startServer() {
  const app = await initializeApp();

  const PORT = process.env.PORT || 3000;
  const NODE_ENV = process.env.NODE_ENV || 'development';

  const server = app.listen(PORT, () => {
    console.log(`✅ Server running on port ${PORT} in ${NODE_ENV} mode`);
  });

  // Graceful shutdown
  process.on('SIGTERM', async () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
    });

    // Clear secrets cache on shutdown
    secretsManager.clearCache();
  });

  // Handle secret rotation
  process.on('SIGUSR2', async () => {
    console.log('🔄 Received secret rotation signal');
    secretsManager.clearCache();

    // Reload secrets
    try {
      appSecrets = await secretsManager.loadAllSecrets();
      console.log('✅ Secrets reloaded successfully');
    } catch (error) {
      console.error('❌ Failed to reload secrets:', error.message);
    }
  });

  return { app, server };
}

// Start server if run directly
if (require.main === module) {
  startServer().catch(error => {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = { initializeApp, createApp, startServer };

/**
 * HashiCorp Vault Integration (Alternative to AWS Secrets Manager)
 * Use this for multi-cloud or on-premise deployments
 */

const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = null;
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
    this.environment = process.env.NODE_ENV || 'development';
  }

  /**
   * Initialize Vault client
   */
  initialize() {
    if (this.environment === 'production' || process.env.USE_VAULT === 'true') {
      const options = {
        apiVersion: 'v1',
        endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
        token: process.env.VAULT_TOKEN, // Use AppRole or Kubernetes auth in production
      };

      this.client = vault(options);
      console.log('✅ HashiCorp Vault initialized');
    } else {
      console.log('⚠️  Development mode: Using local configuration');
    }
  }

  /**
   * Retrieve secret from Vault
   */
  async getSecret(path, useCache = true) {
    if (useCache && this.cache.has(path)) {
      const cached = this.cache.get(path);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    if (!this.client) {
      return this.getLocalSecret(path);
    }

    try {
      const result = await this.client.read(`secret/data/${path}`);
      const secretValue = result.data.data;

      this.cache.set(path, {
        value: secretValue,
        timestamp: Date.now(),
      });

      console.log(`✅ Retrieved secret from Vault: ${path}`);
      return secretValue;

    } catch (error) {
      console.error(`❌ Error retrieving secret from Vault ${path}:`, error.message);
      throw new Error(`Failed to retrieve secret '${path}' from Vault`);
    }
  }

  /**
   * Get local secret for development
   */
  getLocalSecret(path) {
    const localSecrets = {
      'app/database': {
        host: process.env.DB_HOST || 'localhost',
        port: process.env.DB_PORT || 5432,
        database: process.env.DB_NAME || 'dev_db',
        username: process.env.DB_USER || 'dev_user',
        password: process.env.DB_PASSWORD || 'dev_password',
      },
      'app/api-keys': {
        jwtSecret: process.env.JWT_SECRET || 'dev-jwt-secret',
        anthropicApiKey: process.env.ANTHROPIC_API_KEY || '',
        stripeSecretKey: process.env.STRIPE_SECRET_KEY || 'sk-test-dev_key',
      },
    };

    console.log(`⚠️  Using local configuration for: ${path}`);
    return localSecrets[path] || {};
  }

  /**
   * Load all application secrets
   */
  async loadAllSecrets() {
    try {
      const [database, apiKeys, aws, monitoring] = await Promise.all([
        this.getSecret('app/database'),
        this.getSecret('app/api-keys'),
        this.getSecret('app/aws'),
        this.getSecret('app/monitoring'),
      ]);

      return { database, apiKeys, aws, monitoring };
    } catch (error) {
      console.error('❌ Failed to load secrets from Vault:', error.message);
      throw error;
    }
  }

  clearCache() {
    this.cache.clear();
    console.log('🔄 Vault secrets cache cleared');
  }

  validateSecrets(secrets) {
    const required = {
      database: ['host', 'port', 'database', 'username', 'password'],
      apiKeys: ['jwtSecret'],
    };

    const missing = [];

    for (const [category, fields] of Object.entries(required)) {
      if (!secrets[category]) {
        missing.push(`${category} (entire category)`);
        continue;
      }

      for (const field of fields) {
        if (!secrets[category][field]) {
          missing.push(`${category}.${field}`);
        }
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log('✅ All required Vault secrets validated');
  }
}

module.exports = new VaultSecretsManager();

