      // Create a token with the secret from secrets manager
      const token = jwt.sign(
        { userId: 1, role: 'user' },
        'test-jwt-secret-from-manager',
        { expiresIn: '1h' }
      );

      // Should be able to access protected route with valid token
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);

      expect(response.status).toBe(200);
    });

    test('should reject tokens signed with wrong secret', async () => {
      const mockSecrets = {
        database: { host: 'db', password: 'pass' },
        apiKeys: { jwtSecret: 'correct-secret' }
      };

      const app = createApp(mockSecrets);
      const jwt = require('jsonwebtoken');

      // Create token with WRONG secret
      const token = jwt.sign(
        { userId: 1, role: 'user' },
        'wrong-secret',
        { expiresIn: '1h' }
      );

      // Should be rejected
      const response = await request(app)
