#### **Option A: AWS Secrets Manager (Recommended for Production)**

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = {};
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache[secretName];
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT',
      });

      const response = await this.client.send(command);
      const secret = response.SecretString ? JSON.parse(response.SecretString) : response.SecretBinary;

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now(),
      };

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secret');
    }
  }

  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);
    return secret[key];
  }

  clearCache() {
    this.cache = {};
  }
}

module.exports = new SecretsManager();
```

