    ];

    for (const pattern of suspiciousPatterns) {
      if (pattern.test(responseString)) {
        console.error('⚠️ ALERT: Potential secret leak detected in response!');
        console.error(`Path: ${req.path}`);
        console.error(`Method: ${req.method}`);

