// scripts/rotate-credentials.js
// This script rotates credentials WITHOUT exposing them

const fs = require('fs');
const path = require('path');

function getCredentialKeys(envFile) {
  const content = fs.readFileSync(envFile, 'utf8');
  const lines = content.split('\n');
  const keys = [];

  for (const line of lines) {
    if (line.trim() && !line.startsWith('#')) {
      const [key] = line.split('=');
      if (key) {
        keys.push(key.trim());
      }
    }
  }

  return keys;
}

function generateRotationPlan(keys) {
  const plan = {
    timestamp: new Date().toISOString(),
    credentials: keys.map(key => ({
      name: key,
      status: 'pending',
      service: identifyService(key)
    }))
  };

  return plan;
}

function identifyService(key) {
  if (key.includes('DATABASE')) return 'PostgreSQL';
  if (key.includes('AWS')) return 'AWS IAM';
  if (key.includes('ANTHROPIC')) return 'Anthropic';
  if (key.includes('STRIPE')) return 'Stripe';
  if (key.includes('LOGFIRE')) return 'Logfire';
  return 'Unknown';
}

