const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

async function verifyRotation(secretName) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    // Hash the secret for comparison (never log the actual value)
    const secretHash = crypto
      .createHash('sha256')
      .update(response.SecretString)
      .digest('hex');

    console.log(`✅ ${secretName}: Retrieved successfully (hash: ${secretHash.substring(0, 8)}...)`);

    // Check last updated time
    const metadata = await client.send(new GetSecretValueCommand({ 
      SecretId: secretName 
    }));

    console.log(`   Last updated: ${response.CreatedDate || 'N/A'}`);

    return true;
  } catch (error) {
    console.error(`❌ ${secretName}: Failed to verify`);
    return false;
  }
}

