```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = {};
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName] && Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString ? JSON.parse(response.SecretString) : response.SecretBinary;

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  clearCache() {
    this.cache = {};
  }
}

module.exports = new SecretsManager();
```

### 3. **Alternative: HashiCorp Vault Integration**

```javascript
// config/vault.js
const vault = require('node-vault');

class VaultClient {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(path);
      return result.data;
    } catch (error) {
      console.error(`Error reading secret from path ${path}:`, error);
      throw error;
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret('secret/data/database');
  }

  async getAPIKeys() {
    return this.getSecret('secret/data/api-keys');
  }
}

module.exports = new VaultClient();
```

