// config/secrets-rotator.js
class SecretsRotator {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.rotationInterval = 86400000; // 24 hours
  }

  startRotation() {
    setInterval(async () => {
      console.log('Rotating secrets...');
      this.secretsManager.clearCache();
      // Force reload of secrets
      await this.secretsManager.getSecret('production/database');
      console.log('Secrets rotated successfully');
    }, this.rotationInterval);
  }
}

module.exports = SecretsRotator;
