const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN,
    });
  }

  async getSecrets(path) {
    try {
      const response = await this.client.read(path);
      return response.data.data;
    } catch (error) {
      console.error(`Failed to read secrets from path ${path}:`, error);
      throw new Error('Failed to retrieve secrets from Vault');
    }
  }

  async getDatabaseCredentials() {
    // Vault can generate dynamic database credentials
    const creds = await this.client.read('database/creds/myapp-role');
    return {
      username: creds.data.username,
      password: creds.data.password,
      lease_id: creds.lease_id,
      lease_duration: creds.lease_duration,
    };
  }
}

module.exports = new VaultSecretsManager();
