// Secure Application Implementation
// Addresses OWASP Top 10 and common security vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// 1. SECURITY HEADERS (Helmet)
// ============================================
// Protects against: XSS, Clickjacking, MIME sniffing, etc.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));

// ============================================
// 2. CORS CONFIGURATION
// ============================================
// Properly restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// ============================================
// 3. RATE LIMITING
// ============================================
// Protects against: Brute force, DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Stricter limit for sensitive endpoints
  message: 'Too many requests, please try again later.',
});

app.use(generalLimiter);

// ============================================
// 4. BODY PARSING WITH SIZE LIMITS
// ============================================
// Protects against: DoS through large payloads
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// 5. LOGGING (Security & Access Logs)
// ============================================
// In production, use winston or similar for advanced logging
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined')); // Apache-style logs
} else {
  app.use(morgan('dev'));
}

// ============================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================
// Simple JWT/API key authentication example
const authenticateRequest = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  const authHeader = req.headers['authorization'];

  // Example: Check API key or JWT token
  // In production, use proper JWT verification (jsonwebtoken library)
  if (!apiKey && !authHeader) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'Please provide valid credentials'
    });
  }

  // Example API key validation (replace with your actual logic)
  const validApiKeys = process.env.VALID_API_KEYS?.split(',') || [];

  if (apiKey && !validApiKeys.includes(apiKey)) {
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Invalid API key'
    });
  }

  // If using JWT, verify token here
  if (authHeader) {
    const token = authHeader.split(' ')[1];
    // Add JWT verification logic here
    // jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {...})
  }

  next();
};

// ============================================
// 7. INPUT VALIDATION MIDDLEWARE
// ============================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// 8. SANITIZATION HELPER
// ============================================
// Protects against: XSS, injection attacks
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    return data
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;');
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = {};
    for (const key in data) {
      sanitized[key] = sanitizeOutput(data[key]);
    }
    return sanitized;
  }
  return data;
};

// ============================================
// ROUTES
// ============================================

// Health endpoint - minimal information disclosure
app.get('/health', (req, res) => {
  // Don't expose exact timestamp in production
  res.json({ 
    status: 'ok',
    // Only include timestamp in development
    ...(process.env.NODE_ENV !== 'production' && { 
      timestamp: new Date().toISOString() 
    })
  });
});

// Users endpoint - SECURED
app.get('/users', 
  authenticateRequest, // Require authentication
  strictLimiter, // Apply strict rate limiting
  [
    // Input validation for query parameters
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('search').optional().trim().escape()
  ],
  validateRequest,
  (req, res) => {
    try {
      // In production, fetch from database with proper parameterized queries
      // Example with pagination and search
      const page = req.query.page || 1;
      const limit = req.query.limit || 10;

      // Simulated user data (in production, use database)
      // NEVER expose sensitive data like emails without proper authorization
      const users = [
        { id: 1, name: 'Alice', role: 'admin' },
        { id: 2, name: 'Bob', role: 'user' },
      ];

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      // Sanitize output
      const sanitizedUsers = paginatedUsers.map(user => sanitizeOutput(user));

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      // Don't expose error details
      console.error('Error in /users:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Example of secure POST endpoint with validation
app.post('/users',
  authenticateRequest,
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces')
      .escape(),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
    body('role')
      .optional()
      .isIn(['user', 'admin']).withMessage('Invalid role')
  ],
  validateRequest,
  (req, res) => {
    try {
      const { name, email, role } = req.body;

      // In production, use parameterized queries to prevent SQL injection
      // Example with prepared statement:
      // db.query('INSERT INTO users (name, email, role) VALUES (?, ?, ?)', 
      //          [name, email, role])

      const newUser = {
        id: Date.now(), // In production, use database auto-increment
        name: sanitizeOutput(name),
        email: sanitizeOutput(email),
        role: role || 'user'
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler - NEVER expose stack traces in production
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Log full error details for debugging
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  res.status(err.status || 500).json({
    error: 'Internal server error',
    // Only include error details in development
    ...(process.env.NODE_ENV !== 'production' && { 
      message: err.message,
      stack: err.stack 
    })
  });
});

// ============================================
// SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;

// Use HTTPS in production
if (process.env.NODE_ENV === 'production') {
  // Ensure HTTPS is used
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

