// Secure Secrets Management with AWS Secrets Manager
// Replace .env file with proper secrets management

const express = require('express');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes cache
  }

  /**
   * Retrieve a secret from AWS Secrets Manager
   * @param {string} secretName - The name/ARN of the secret
   * @param {boolean} forceRefresh - Force refresh from AWS (bypass cache)
   * @returns {Promise<Object>} - The secret value
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first (unless force refresh)
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log(`[Secrets] Using cached value for: ${secretName}`);
        return cached.value;
      }
    }

    try {
      console.log(`[Secrets] Fetching from AWS: ${secretName}`);
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`[Secrets] Error fetching secret ${secretName}:`, error);

      // Fail securely - don't start app with missing secrets
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      if (error.name === 'AccessDeniedException') {
        throw new Error(`Access denied to secret: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get multiple secrets at once
   * @param {Array<string>} secretNames - Array of secret names
   * @returns {Promise<Object>} - Object with all secrets
   */
  async getSecrets(secretNames) {
    const secrets = {};
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }

  /**
   * Clear secret cache (useful for rotation)
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`[Secrets] Cache cleared for: ${secretName}`);
    } else {
      this.cache.clear();
      console.log('[Secrets] All cache cleared');
    }
  }

  /**
   * Get individual secret value from a JSON secret
   * @param {string} secretName - The secret name
   * @param {string} key - The key within the JSON secret
   * @returns {Promise<string>} - The value
   */
  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);
    if (typeof secret === 'object' && secret[key]) {
      return secret[key];
    }
    throw new Error(`Key ${key} not found in secret ${secretName}`);
  }
}

// Initialize secrets manager
const secretsManager = new SecretsManager();

/**
 * Load all required secrets at application startup
 * This ensures all secrets are available before the app starts
 */
async function loadSecrets() {
  try {
    console.log('[Secrets] Loading application secrets...');

    // Load application secrets from AWS Secrets Manager
    const appSecrets = await secretsManager.getSecret('prod/myapp/config');

    // Store in process.env for compatibility with existing code
    // (Alternative: export as a config object)
    process.env.JWT_SECRET = appSecrets.JWT_SECRET;
    process.env.SESSION_SECRET = appSecrets.SESSION_SECRET;
    process.env.DATABASE_URL = appSecrets.DATABASE_URL;

    // Load API keys
    const apiKeys = await secretsManager.getSecret('prod/myapp/api-keys');
    process.env.VALID_API_KEYS = Object.values(apiKeys).join(',');

    // Load third-party service credentials
    const awsCreds = await secretsManager.getSecret('prod/myapp/aws-credentials');
    process.env.AWS_ACCESS_KEY_ID = awsCreds.AWS_ACCESS_KEY_ID;
    process.env.AWS_SECRET_ACCESS_KEY = awsCreds.AWS_SECRET_ACCESS_KEY;

    // Load payment provider secrets (if needed)
    if (process.env.ENABLE_PAYMENTS === 'true') {
      const paymentSecrets = await secretsManager.getSecret('prod/myapp/stripe');
      process.env.STRIPE_SECRET_KEY = paymentSecrets.STRIPE_SECRET_KEY;
    }

    console.log('[Secrets] All secrets loaded successfully');
    return true;
  } catch (error) {
    console.error('[Secrets] FATAL: Failed to load secrets:', error);
    // Don't start the application if secrets can't be loaded
    process.exit(1);
  }
}

/**
 * Setup automatic secret rotation handler
 * AWS Secrets Manager can trigger Lambda functions for rotation
 */
function setupSecretRotationHandler(app) {
  // Endpoint for AWS Secrets Manager rotation (secured by API Gateway)
  app.post('/internal/secrets/rotate', async (req, res) => {
    // Verify request is from AWS (check source IP, signature, etc.)
    const authToken = req.headers['x-rotation-token'];
    if (authToken !== process.env.ROTATION_TOKEN) {
      return res.status(403).json({ error: 'Unauthorized' });
    }

    const { secretName } = req.body;

    try {
      // Clear cache for the rotated secret
      secretsManager.clearCache(secretName);

      // Reload the secret
      await secretsManager.getSecret(secretName, true);

      console.log(`[Secrets] Secret rotated successfully: ${secretName}`);
      res.json({ success: true, message: 'Secret rotated' });
    } catch (error) {
      console.error(`[Secrets] Failed to rotate secret ${secretName}:`, error);
      res.status(500).json({ error: 'Rotation failed' });
    }
  });
}

// Export for use in application
module.exports = {
  secretsManager,
  loadSecrets,
  setupSecretRotationHandler
};

// Example usage in main app:
