```javascript
// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (err) {
      console.error(`Error retrieving secret ${secretName}:`, err.message);
      throw new Error('Failed to retrieve secret');
    }
  }

  async loadAllSecrets() {
    const secretNames = [
      'prod/database',
      'prod/stripe',
      'prod/anthropic',
      'prod/aws',
      'prod/logfire'
    ];

    const secrets = {};
    for (const name of secretNames) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (err) {
        console.error(`Failed to load secret: ${name}`);
        // Fail fast - don't start app without required secrets
        process.exit(1);
      }
    }

    return secrets;
  }

  // Rotate secrets periodically
  async rotateSecret(secretName) {
    try {
      await this.client.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
      }).promise();

      // Clear cache to force reload
      this.cache.delete(secretName);
    } catch (err) {
      console.error(`Failed to rotate secret ${secretName}:`, err.message);
      throw err;
    }
  }
}

module.exports = new SecretsManager();
```

