// config/vault.js
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN // Only for initial auth
    });
    this.secrets = {};
  }

  async authenticate() {
    // Use Kubernetes/AWS/Azure auth in production
    try {
      const result = await this.client.kubernetesLogin({
        role: process.env.VAULT_ROLE,
        jwt: fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8')
      });

      this.client.token = result.auth.client_token;

      // Renew token before expiry
      this.setupTokenRenewal(result.auth.lease_duration);
    } catch (err) {
      console.error('Vault authentication failed:', err.message);
      throw err;
    }
  }

  setupTokenRenewal(leaseDuration) {
    // Renew token at 80% of lease duration
    const renewalTime = leaseDuration * 0.8 * 1000;

    setTimeout(async () => {
      try {
        await this.client.tokenRenewSelf();
        this.setupTokenRenewal(leaseDuration);
      } catch (err) {
        console.error('Token renewal failed:', err.message);
        // Re-authenticate
        await this.authenticate();
      }
    }, renewalTime);
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(`secret/data/${path}`);
      return result.data.data;
    } catch (err) {
      console.error(`Failed to read secret at ${path}:`, err.message);
      throw err;
    }
  }

  async loadSecrets() {
    const paths = [
      'prod/database',
      'prod/stripe',
      'prod/anthropic',
      'prod/aws',
      'prod/logfire'
    ];

    for (const path of paths) {
      this.secrets[path] = await this.getSecret(path);
    }

    return this.secrets;
  }
}

module.exports = new VaultSecretsManager();
