// config/azure-keyvault.js
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureSecretsManager {
  constructor() {
    const vaultUrl = process.env.AZURE_KEYVAULT_URL;

    if (!vaultUrl) {
      throw new Error('AZURE_KEYVAULT_URL not configured');
    }

    // Use managed identity in production
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
    this.cache = new Map();
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const secret = await this.client.getSecret(secretName);
      this.cache.set(secretName, secret.value);
      return secret.value;
    } catch (err) {
      console.error(`Failed to retrieve secret ${secretName}:`, err.message);
      throw err;
    }
  }

  async loadAllSecrets() {
    const secretNames = [
      'database-url',
      'stripe-secret-key',
      'anthropic-api-key',
      'aws-access-key',
      'aws-secret-key',
      'logfire-token'
    ];

    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }

    return secrets;
  }
}

module.exports = new AzureSecretsManager();
